<?php
namespace App\Policies;use App\Models\{User,RenewalCase};final class RenewalCasePolicy{private function a(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','RENEWAL_MANAGER'])->exists()||$this->broker($u);}
/** P6 2026-09-29 (portals writable): inside /broker, holders of broker.portal.read see the renewal cases of their own book (the policy must be theirs, PortalScope::isOwnRecord); re-quote / link still need renewals.manage on the action. */
private function broker(User$u):bool{return \App\Application\WebExperiences\PortalScope::panel()==='broker'&&(bool)rescue(fn()=>$u->hasPermission('broker.portal.read'),false,false);}
public function viewAny(User$u):bool{return$this->a($u);}public function view(User$u,RenewalCase$m):bool{return$this->a($u)&&$m->tenant_id===app(\App\Domain\Tenancy\TenantContext::class)->id()&&(\App\Application\WebExperiences\PortalScope::panel()===null||($m->policy!==null&&\App\Application\WebExperiences\PortalScope::isOwnRecord($m->policy)));}public function create(User$u):bool{return$this->a($u);}public function update(User$u,RenewalCase$m):bool{return$this->view($u,$m);}public function delete(User$u,RenewalCase$m):bool{return false;}}
